func:
// Zweck: Gemeinsamer Einstiegspunkt für ALLE fünf Device-Nachrichtentypen.
// Vorher gab es fünf separate, identisch aufgebaute Functions – das war reines Copy-Paste.
// Jetzt rufen alle fünf Link-In-Nodes diesen einen Handler auf.
//
// Eingaben:
//   msg.sh        – Routing-State aus dem Ingest-Tab (scope, topic_type, entity_id, received_at)
//   msg.payload   – bereits geparster JSON-Payload aus MQTT
//
// Ausgaben:
//   msg.payload       – aktualisiertes Geräteobjekt (für nachgelagerte Flows)
//   msg.sqlite_batch  – vorbereitete SQL-Statements für den zentralen Persistenz-Tab
//
// Seiteneffekt:
//   smarthome_runtime (global) wird mit dem aktualisierten Gerät überschrieben.

const topicHandlers = global.get("topicHandlers");

// Sicherheitscheck: Lib-Helper müssen vorhanden sein.
// Fehlt topicHandlers, hat der Boot-Flow nicht korrekt abgeschlossen
// oder ein Teil-Redeploy hat den globalen Kontext geleert.
if (!topicHandlers || typeof topicHandlers.handleRoutedMessage !== "function") {
    node.error("topicHandlers fehlt – Boot-Flow prüfen (00_boot)", msg);
    return null;
}

// Den Nachrichtentyp für aussagekräftige Warn-Meldungen merken.
// msg.sh.topic_type enthält z. B. 'meta', 'state', 'event' usw.
const topicType = (msg.sh && msg.sh.topic_type) ? msg.sh.topic_type : "unbekannt";

// Fachlogik aus der Lib aufrufen.
// handleRoutedMessage kümmert sich um die korrekte Verarbeitung je topic_type.
const result = topicHandlers.handleRoutedMessage(
    global.get("smarthome_runtime"),
    msg.sh,
    msg.payload
);

// Wenn kein Gerät erkannt wurde (fehlende device_id im Payload), Nachricht verwerfen.
if (!result || !result.payload || !result.payload.device) {
    node.warn(`${topicType}: Gerät nicht erkennbar (device_id fehlt im Payload)`);
    return null;
}

// Aktualisierten Runtime-State in den globalen Kontext zurückschreiben.
global.set("smarthome_runtime", result.runtime);

// Ergebnis für nachgelagerte Nodes setzen.
msg.payload      = result.payload;
msg.sqlite_batch = result.sqlite_batch || null;
return msg;
